    "format": "text-only",
    "targetAudience": "Sales Leaders, RevOps Directors & GTM Enablement Leads",
    "contentBrief": "Show how teams can replace unfocused status reporting with decisions about risks, blockers, priorities, and next actions.",
    "mdPath": "text-only/revenue-team-efficiency/036-making-revenue-meetings-more-useful.md",
