    "format": "single-image",
    "targetAudience": "CROs, Revenue Operations Directors & Enterprise Sales Executives",
    "contentBrief": "Challenge activity-only reporting and explain how to connect activity quality with opportunity progression, conversion, and commercial outcomes.",
    "mdPath": "single-image/revenue-intelligence/065-connecting-activity-metrics-to-business-outcomes.md",
    "htmlPath": "single-image/revenue-intelligence/065-connecting-activity-metrics-to-business-outcomes.html",
